<div class="d-flex justify-content-between mb-3"><div><h1 class="h3">解析记录</h1><p class="mono text-muted"><?= h($sub['fqdn']) ?></p></div><a class="btn btn-light" href="<?= h(url_to('index/dns/index')) ?>">返回</a></div><div class="card mb-4"><div class="card-body"><form method="post" class="row g-2"><?= csrf_field() ?><input type="hidden" name="record_id" id="record_id"><div class="col-md-2"><label class="form-label">主机</label><input class="form-control" name="host" id="host" value="@"></div><div class="col-md-2"><label class="form-label">类型</label><select class="form-select" name="type" id="type"><?php foreach ($types as $t): ?><option><?= h($t) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">值</label><input class="form-control" name="value" id="value" required></div><div class="col-md-2"><label class="form-label">TTL（最小 <?= h($minTtl) ?>）</label><input class="form-control" type="number" name="ttl" id="ttl" min="<?= h($minTtl) ?>" value="<?= h($domain['default_ttl']) ?>"></div><div class="col-md-1"><label class="form-label">MX</label><input class="form-control" type="number" name="mx" id="mx" value="10"></div><input type="hidden" name="line" value="default"><?php if ($proxyEnabled): ?><div class="col-md-2 form-check mt-4"><input class="form-check-input" type="checkbox" name="proxied" value="1" id="proxied"><label class="form-check-label" for="proxied">Cloudflare 代理</label></div><?php endif; ?><div class="col-12"><button class="btn btn-primary">保存记录</button></div></form></div></div><div class="table-card table-responsive"><table class="table align-middle"><thead><tr><th>主机</th><th>类型</th><th>值</th><th>TTL</th><th>状态</th><th></th></tr></thead><tbody><?php foreach ($protected as $r): ?><tr class="table-warning"><td><?= h($r['name']) ?></td><td><?= h($r['type']) ?></td><td class="mono"><?= h($r['value']) ?></td><td colspan="2">域名原有记录，不可修改</td><td></td></tr><?php endforeach; ?><?php foreach ($records as $r): ?><tr><td><?= h($r['host']) ?></td><td><?= h($r['type']) ?></td><td class="mono"><?= h($r['value']) ?></td><td><?= h($r['ttl']) ?></td><td><?= status_badge($r['status'], 'record') ?></td><td><button class="btn btn-sm btn-outline-primary" onclick='editRecord(<?= json_encode($r) ?>)'>编辑</button><form class="d-inline" method="post" action="<?= h(url_to('index/dns/deleteRecord')) ?>" data-confirm="确定删除？"><?= csrf_field() ?><input type="hidden" name="id" value="<?= h($r['id']) ?>"><button class="btn btn-sm btn-outline-danger">删除</button></form></td></tr><?php endforeach; ?></tbody></table></div><script>function editRecord(r){['record_id','host','type','value','ttl','mx'].forEach(function(k){document.getElementById(k).value=r[k]||''});window.scrollTo(0,0);}</script>
